entries.action:
{async () => {
            if (!walkin) return;
            try {
              await productsApi.createSale({
                paymentMethod: walkin.paymentMethod,
                items: walkin.items,
                discount: walkin.discount,
                clientId: walkin.clientId,
                idempotencyKey: walkin.idempotencyKey,
              });
              onNotify?.('Venda concluída.', 'success');
              setWalkin(null);
              idempotencyRef.current = null;
              await load();
              onReload();
            } catch (err) {
              onNotify?.(getErrorMessage(err, 'Não foi possível concluir a venda.'), 'error');
            }
          }}

{async () => {
          if (!reverseReceipt || reverseReason.trim().length < 3) {
            onNotify?.('Informe um motivo com pelo menos 3 caracteres.', 'error');
            return;
          }
          try {
            await productsApi.reverseReceipt(reverseReceipt.id, { reason: reverseReason.trim() });
            onNotify?.('Compra estornada.', 'success');
            setReverseReceipt(null);
            setReverseReason('');
            await load();
            onReload();
          } catch (err) {
            onNotify?.(getErrorMessage(err, 'Não foi possível estornar a compra.'), 'error');
          }
        }}

{e =>
